From b79388b367a540b5358eef2b24b8a3fe1540fcf1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:27:46 +0100
Subject: [PATCH] input: offer windows moved over a panel as a drag

Dragging a window by its titlebar onto the pager did nothing, since the
panel never saw the move. Now the window is offered to panels as a drag
and keeps its old position if the drop sends it to another desktop.

BUG: 488419
---
 src/input.cpp | 164 +++++++++++++++++++++++++++++++++++++++++++++++++-
 1 file changed, 161 insertions(+), 3 deletions(-)

diff --git a/src/input.cpp b/src/input.cpp
index 327e713bc3..ca8675c164 100644
--- a/src/input.cpp
+++ b/src/input.cpp
@@ -2571,6 +2571,69 @@ static AbstractDropHandler *dropHandler(Window *window)
     return nullptr;
 }

+/**
+ * Offers a window that is being moved to panels, so that widgets like the pager can take it.
+ */
+class WindowDragSource : public AbstractDataSource
+{
+public:
+    explicit WindowDragSource(const QUuid &windowId, std::function<void()> finished)
+        : m_windowId(windowId.toString().toUtf8())
+        , m_finished(std::move(finished))
+    {
+    }
+    ~WindowDragSource() override
+    {
+        Q_EMIT aboutToBeDestroyed();
+    }
+
+    void requestData(const QString &mimeType, FileDescriptor fd) override
+    {
+        if (mimeType == mimeTypes().constFirst()) {
+            if (::write(fd.get(), m_windowId.constData(), m_windowId.size()) == -1) {
+                qCWarning(KWIN_CORE) << "Failed to send the dragged window id:" << strerror(errno);
+            }
+        }
+    }
+    void cancel() override
+    {
+    }
+    QStringList mimeTypes() const override
+    {
+        return {QStringLiteral("application/x-kde-window-uuid")};
+    }
+    void accept(const QString &mimeType) override
+    {
+        m_accepted = !mimeType.isEmpty();
+    }
+    bool isAccepted() const override
+    {
+        return m_accepted;
+    }
+    DnDActions supportedDragAndDropActions() const override
+    {
+        return DnDAction::Move;
+    }
+    DnDAction selectedDndAction() const override
+    {
+        return m_action;
+    }
+    void dndAction(DnDAction action) override
+    {
+        m_action = action;
+    }
+    void dndFinished() override
+    {
+        m_finished();
+    }
+
+private:
+    const QByteArray m_windowId;
+    const std::function<void()> m_finished;
+    DnDAction m_action = DnDAction::None;
+    bool m_accepted = false;
+};
+
 class DragAndDropInputFilter : public QObject, public InputEventFilter
 {
     Q_OBJECT
@@ -2636,16 +2699,37 @@ public:
                 workspace()->requestFocus(m_currentToplevelDragWindow);
                 m_currentToplevelDragWindow = nullptr;
             }
+            if (Window *window = std::exchange(m_windowDragWindow, nullptr); window && window->isInteractiveMove()) {
+                if (!m_windowDragSource->isDropPerformed()) {
+                    // The pointer left the panel, keep moving the window
+                } else if (m_windowDragSource->isDndCancelled()) {
+                    window->endInteractiveMoveResize();
+                } else {
+                    // Wait until the panel has handled the drop to see what it did with the window
+                    m_droppedWindow = window;
+                    m_dropTimer.start();
+                }
+            }
         });

         m_raiseTimer.setSingleShot(true);
         m_raiseTimer.setInterval(1000);
         connect(&m_raiseTimer, &QTimer::timeout, this, &DragAndDropInputFilter::raiseDragTarget);
+
+        m_dropTimer.setSingleShot(true);
+        m_dropTimer.setInterval(1000);
+        connect(&m_dropTimer, &QTimer::timeout, this, &DragAndDropInputFilter::finishWindowDrop);
     }

     bool pointerMotion(PointerMotionEvent *event) override
     {
         auto seat = waylandServer()->seat();
+        if (m_droppedWindow) {
+            return true;
+        }
+        if (!seat->isDrag()) {
+            startWindowDrag(event->position);
+        }
         if (!seat->isDragPointer()) {
             return false;
         }
@@ -2660,6 +2744,9 @@ public:
     bool pointerButton(PointerButtonEvent *event) override
     {
         auto seat = waylandServer()->seat();
+        if (m_droppedWindow) {
+            return true;
+        }
         if (!seat->isDragPointer()) {
             return false;
         }
@@ -2667,7 +2754,12 @@ public:
             return true;
         }
         seat->setTimestamp(event->timestamp);
-        if (event->state == PointerButtonState::Pressed) {
+        if (isWindowDrag()) {
+            // The panel never saw the press that started the move, so end the drag here
+            if (event->state == PointerButtonState::Released && event->buttons == Qt::NoButton) {
+                seat->endDrag();
+            }
+        } else if (event->state == PointerButtonState::Pressed) {
             seat->notifyPointerButton(event->nativeButton, event->state);
         } else {
             raiseDragTarget();
@@ -2754,6 +2846,12 @@ public:
             return false;
         }

+        if (isWindowDrag()) {
+            // Let Escape cancel the window move as well
+            seat->cancelDrag();
+            return false;
+        }
+
         seat->cancelDrag();

         return true;
@@ -2831,7 +2929,7 @@ private:
             if (auto toplevelDrag = waylandServer()->seat()->xdgTopleveldrag(); toplevelDrag && toplevelDrag->toplevel() && toplevelDrag->toplevel()->surface() == window->surface()) {
                 continue;
             }
-            if (window->isDeleted()) {
+            if (window->isDeleted() || window == m_windowDragWindow) {
                 continue;
             }
             if (!window->isClient()) {
@@ -2881,8 +2979,20 @@ private:
             window->updateInteractiveMoveResize(position, input()->keyboardModifiers());
         }

+        if (isWindowDrag()) {
+            if (!m_windowDragWindow) {
+                seat->cancelDrag();
+                return;
+            }
+            m_windowDragWindow->updateInteractiveMoveResize(position, input()->keyboardModifiers());
+        }
+
         Window *dragTarget = pickDragTarget(position);
-        if (dragTarget) {
+        if (isWindowDrag() && (!dragTarget || !dragTarget->isDock())) {
+            seat->cancelDrag();
+            return;
+        }
+        if (dragTarget && !isWindowDrag()) {
             if (dragTarget != m_dragTarget) {
                 workspace()->requestFocus(dragTarget);
                 m_raiseTimer.start();
@@ -2916,11 +3026,59 @@ private:
         }
     }

+    bool isWindowDrag() const
+    {
+        return m_windowDragSource && waylandServer()->seat()->dragSource() == m_windowDragSource.get();
+    }
+
+    void startWindowDrag(const QPointF &position)
+    {
+        Window *window = workspace()->moveResizeWindow();
+        if (!window || !window->isInteractiveMove() || input()->qtButtonStates() == Qt::NoButton) {
+            return;
+        }
+        m_windowDragWindow = window;
+        Window *target = pickDragTarget(position);
+        if (!target || !target->isDock()) {
+            m_windowDragWindow = nullptr;
+            return;
+        }
+        m_windowDragDesktops = window->desktops();
+        m_windowDragActivities = window->activities();
+        m_windowDragSource = std::make_unique<WindowDragSource>(window->internalId(), [this] {
+            finishWindowDrop();
+        });
+        if (!waylandServer()->seat()->startPointerDrag(m_windowDragSource.get(), nullptr, position, QMatrix4x4(), 0, nullptr)) {
+            m_windowDragWindow = nullptr;
+        }
+    }
+
+    void finishWindowDrop()
+    {
+        m_dropTimer.stop();
+        Window *window = std::exchange(m_droppedWindow, nullptr);
+        if (!window || !window->isInteractiveMove()) {
+            return;
+        }
+        if (window->desktops() != m_windowDragDesktops || window->activities() != m_windowDragActivities) {
+            // The pager sent the window elsewhere, keep it where it was before the move
+            window->cancelInteractiveMoveResize();
+        } else {
+            window->endInteractiveMoveResize();
+        }
+    }
+
     std::optional<QPointF> m_lastPos = std::nullopt;
     QPointer<Window> m_dragTarget;
     QTimer m_raiseTimer;
     QPointer<Window> m_currentToplevelDragWindow = nullptr;
     bool m_wasKeepAbove = false;
+    std::unique_ptr<WindowDragSource> m_windowDragSource;
+    QPointer<Window> m_windowDragWindow;
+    QList<VirtualDesktop *> m_windowDragDesktops;
+    QStringList m_windowDragActivities;
+    QPointer<Window> m_droppedWindow;
+    QTimer m_dropTimer;
 };

 KWIN_SINGLETON_FACTORY(InputRedirection)
