From 3c53974edc0dade7a30c8882ec556107ac05cecd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:27:46 +0100
Subject: [PATCH] applets/pager: send windows dropped by their titlebar to that
 desktop

KWin offers a window moved over a panel as a drag carrying its id. The
pager now sends that window to the desktop it's dropped on, while the
task manager ignores it so crossing tasks doesn't activate them.

BUG: 488419
---
 applets/pager/pagermodel.cpp             | 8 +++++++-
 applets/taskmanager/qml/MouseHandler.qml | 3 ++-
 2 files changed, 9 insertions(+), 2 deletions(-)

diff --git a/applets/pager/pagermodel.cpp b/applets/pager/pagermodel.cpp
index 6e476f3d15..ccb14760af 100644
--- a/applets/pager/pagermodel.cpp
+++ b/applets/pager/pagermodel.cpp
@@ -535,7 +535,13 @@ void PagerModel::drop(QMimeData *mimeData, int modifiers, const QVariant &itemId
     bool ok = false;
     QList<QModelIndex> indices;
     if (KWindowSystem::isPlatformWayland()) {
-        indices = findWindows(TaskManager::WaylandTasksModel::winIdsFromMimeData(mimeData, &ok));
+        // A window dragged by its titlebar, offered by KWin
+        if (const QUuid id(mimeData->data(QStringLiteral("application/x-kde-window-uuid"))); !id.isNull()) {
+            ok = true;
+            indices = findWindows(QList<QUuid>{id});
+        } else {
+            indices = findWindows(TaskManager::WaylandTasksModel::winIdsFromMimeData(mimeData, &ok));
+        }
     }
     if (!ok) {
         return;
diff --git a/applets/taskmanager/qml/MouseHandler.qml b/applets/taskmanager/qml/MouseHandler.qml
index 2fd85860c2..85daa93a55 100644
--- a/applets/taskmanager/qml/MouseHandler.qml
+++ b/applets/taskmanager/qml/MouseHandler.qml
@@ -24,7 +24,8 @@ DropArea {

     //ignore anything that is neither internal to TaskManager or a URL list
     onEntered: event => {
-        if (event.formats.indexOf("text/x-plasmoidservicename") >= 0) {
+        if (event.formats.indexOf("text/x-plasmoidservicename") >= 0
+                || event.formats.indexOf("application/x-kde-window-uuid") >= 0) {
             event.accepted = false;
         }
         if (target.animating) { // Not all targets have an animating property
